function ____exports.createIntro(parent, onFinish)
    local WHEEL_CY
    local W = View.size.width
    local H = View.size.height
    local MX = W / 2 - 190
    local MY = H / 2 - 150
    local MR = 110
    local TX = W / 2 - 250
    local TBY = -H / 2 + 140
    local TTH = 300
    local TTY = TBY + TTH
    local BANK = -H / 2 + 120
    local SUBY = -H / 2 + 90
    local WHEEL_R = 95
    local root = Node()
    root:addTo(parent)
    local sceneRoot = Node()
    sceneRoot:addTo(root)
    local bgDraw = DrawNode()
    bgDraw:addTo(sceneRoot)
    local sceneDraw = DrawNode()
    sceneDraw:addTo(sceneRoot)
    local fxDraw = DrawNode()
    fxDraw:addTo(root)
    local uiDraw = DrawNode()
    uiDraw:addTo(root)
    playBgm("dusk", 1.5)
    local DUSK_DEFS = {
        {file = "far_clouds.png", speed = 2},
        {file = "far_mountains.png", speed = 1},
        {file = "mountains.png", speed = 4},
        {file = "near_clouds.png", speed = 7},
        {file = "trees.png", speed = 10}
    }
    local duskRoot = Node()
    duskRoot:addTo(sceneRoot)
    local duskLayers = {}
    local moonDraw = DrawNode()
    local function loadDuskLayer(file, speed)
        local tex = Texture2D("assets/bg/dusk/" .. file)
        if tex == nil then
            return false
        end
        local sy = H / tex.height
        local tileW = tex.width * sy
        local count = Math:ceil(W / tileW) + 1
        local sprites = {}
        do
            local j = 0
            while j < count do
                local sp = Sprite(tex)
                sp.filter = "Point"
                sp.scaleX = sy
                sp.scaleY = sy
                sp.position = Vec2(-W / 2 + tileW / 2 + j * tileW, 0)
                sp:addTo(duskRoot)
                sprites:push(sp)
                j = j + 1
            end
        end
        duskLayers:push({sprites = sprites, tileW = tileW, speed = speed})
        return true
    end
    local duskOk = false
    do
        local skyTex = Texture2D("assets/bg/dusk/sky.png")
        if skyTex ~= nil then
            local sky = Sprite(skyTex)
            sky.filter = "Point"
            sky.scaleX = W / skyTex.width
            sky.scaleY = H / skyTex.height
            sky.position = Vec2(0, 0)
            sky:addTo(duskRoot)
            duskOk = loadDuskLayer(DUSK_DEFS[1].file, DUSK_DEFS[1].speed) and loadDuskLayer(DUSK_DEFS[2].file, DUSK_DEFS[2].speed)
            moonDraw:addTo(duskRoot)
            duskOk = duskOk and loadDuskLayer(DUSK_DEFS[3].file, DUSK_DEFS[3].speed) and loadDuskLayer(DUSK_DEFS[4].file, DUSK_DEFS[4].speed) and loadDuskLayer(DUSK_DEFS[5].file, DUSK_DEFS[5].speed)
        end
    end
    if not duskOk then
        __TS__ArraySetLength(duskLayers, 0)
        duskRoot.visible = false
    end
    local cardSp
    local cardTex = Texture2D("assets/art/yanyue-key-visual.png")
    if cardTex ~= nil then
        local s = Math:max(W / cardTex.width, H / cardTex.height)
        local sp = Sprite(cardTex)
        sp.scaleX = s
        sp.scaleY = s
        sp.position = Vec2(0, 0)
        sp.opacity = 0
        sp.visible = false
        sp:addTo(sceneRoot)
        cardSp = sp
    end
    local hintLb = Label("sarasa-mono-sc-regular", 15)
    if hintLb ~= nil then
        hintLb.text = "按 J 跳过序章"
        hintLb.color = col(Palette.paleInk)
        hintLb.anchor = Vec2(1, 0.5)
        hintLb.position = Vec2(W / 2 - 24, H / 2 - 26)
        hintLb:addTo(root)
    end
    local subLb = Label("sarasa-mono-sc-regular", 26)
    if subLb ~= nil then
        subLb.color = col(Palette.inkDark)
        subLb.anchor = Vec2(0.5, 0.5)
        subLb.position = Vec2(0, SUBY)
        subLb:addTo(root)
    end
    local BUBX = -150
    local BUBY = BANK + 128
    local bubLb = Label("sarasa-mono-sc-regular", 20)
    if bubLb ~= nil then
        bubLb.text = "你是谁？"
        bubLb.color = col(Palette.inkDark)
        bubLb.anchor = Vec2(0.5, 0.5)
        bubLb.position = Vec2(BUBX, BUBY)
        bubLb:addTo(root)
        bubLb.visible = false
    end
    local function ridgeY(wx, base, amp, seed)
        return base + amp * (0.55 * Math:sin(wx * 0.0042 + seed) + 0.3 * Math:sin(wx * 0.0113 + seed * 2.1) + 0.15 * Math:sin(wx * 0.027 + seed * 0.7))
    end
    local function drawRidge(d, base, amp, seed, drift, c)
        local pts = {}
        do
            local x = -W / 2 - 60
            while x <= W / 2 + 60 do
                pts:push(Vec2(
                    x,
                    ridgeY(x + drift, base, amp, seed)
                ))
                x = x + 48
            end
        end
        pts:push(Vec2(W / 2 + 60, -H / 2 - 80))
        pts:push(Vec2(-W / 2 - 60, -H / 2 - 80))
        d:drawPolygon(pts, c)
    end
    local function drawTown(d, c)
        local y0 = -H / 2 + 96
        local pts = {Vec2(-W / 2 - 40, y0)}
        local x = -W / 2 - 20
        local i = 0
        while x < 40 do
            local w = 64 + hash(i * 5.7) * 26
            local hgt = 22 + hash(i * 3.1) * 18
            pts:push(Vec2(x + w * 0.5, y0 + hgt))
            pts:push(Vec2(x + w, y0 + 6))
            x = x + w
            i = i + 1
        end
        pts:push(Vec2(x, -H / 2 - 80))
        pts:push(Vec2(-W / 2 - 40, -H / 2 - 80))
        d:drawPolygon(pts, c)
        d:drawPolygon(
            rectPts(-W / 2 + 34, y0 + 6, 30, 74),
            c
        )
        d:drawPolygon(
            {
                Vec2(-W / 2 + 24, y0 + 80),
                Vec2(-W / 2 + 74, y0 + 80),
                Vec2(-W / 2 + 49, y0 + 104)
            },
            c
        )
    end
    local function drawTower(d, a)
        if a <= 0.01 then
            return
        end
        local cBody = col(Palette.paleInkMid, a)
        local cTop = col(Palette.inkSoft, a)
        do
            local i = 0
            while i < 5 do
                local w = 150 - i * 20
                local y = TBY + i * 56
                local hw = w - 14
                d:drawPolygon(
                    {
                        Vec2(TX - w / 2, y),
                        Vec2(TX + w / 2, y),
                        Vec2(TX + hw / 2, y + 56),
                        Vec2(TX - hw / 2, y + 56)
                    },
                    cBody
                )
                d:drawPolygon(
                    rectPts(TX - hw / 2 + 16, y + 32, hw - 32, 10),
                    col(Palette.paper, a * 0.85)
                )
                i = i + 1
            end
        end
        local py = TBY + 5 * 56
        d:drawPolygon(
            rectPts(TX - 95, py, 190, 10),
            cTop
        )
        d:drawPolygon(
            {
                Vec2(TX - 100, py + 10),
                Vec2(TX + 100, py + 10),
                Vec2(TX + 30, py + 46),
                Vec2(TX - 30, py + 46)
            },
            cTop
        )
        d:drawSegment(
            Vec2(TX, py + 46),
            Vec2(TX, py + 66),
            4,
            cTop
        )
        d:drawDot(
            Vec2(TX, py + 70),
            5,
            cTop
        )
        local stC = col(Palette.inkSoft, a * 0.7)
        d:drawSegment(
            Vec2(TX - 96, TBY + 4),
            Vec2(TX - 60, TBY + 56),
            3,
            stC
        )
        d:drawSegment(
            Vec2(TX - 60, TBY + 56),
            Vec2(TX - 96, TBY + 112),
            3,
            stC
        )
        d:drawSegment(
            Vec2(TX - 96, TBY + 112),
            Vec2(TX - 60, TBY + 168),
            3,
            stC
        )
        d:drawSegment(
            Vec2(TX - 60, TBY + 168),
            Vec2(TX - 96, TBY + 224),
            3,
            stC
        )
        d:drawSegment(
            Vec2(TX - 96, TBY + 224),
            Vec2(TX - 40, py + 4),
            3,
            stC
        )
    end
    local function drawFigure(d, x, y, s, a, female, pose)
        if a <= 0.01 then
            return
        end
        local c = col(Palette.inkDark, a)
        local lw = 3 * s
        local function seg(x1, y1, x2, y2)
            d:drawSegment(
                Vec2(x + x1 * s, y + y1 * s),
                Vec2(x + x2 * s, y + y2 * s),
                lw,
                c
            )
        end
        if pose == "lie" then
            d:drawDot(
                Vec2(x - 16 * s, y + 5 * s),
                4.5 * s,
                c
            )
            seg(-10, 5, 14, 7)
            seg(14, 7, 32, 3)
            seg(-10, 6, 6, 12)
            return
        end
        if pose == "kneel" then
            d:drawDot(
                Vec2(x, y + 24 * s),
                4.5 * s,
                c
            )
            seg(0, 20, 0, 8)
            seg(0, 8, -8, 2)
            seg(0, 8, 6, 1)
            seg(0, 17, 9, 9)
            seg(0, 15, -7, 9)
            if female then
                d:drawSegment(
                    Vec2(x - 3 * s, y + 26 * s),
                    Vec2(x - 9 * s, y + 18 * s),
                    lw * 0.9,
                    c
                )
            end
            return
        end
        d:drawDot(
            Vec2(x, y + 30 * s),
            4.5 * s,
            c
        )
        seg(0, 26, 0, 12)
        if pose == "walk" then
            seg(0, 12, -7 * s, 0)
            seg(0, 12, 7 * s, 0)
            seg(0, 23, -6 * s, 16)
            seg(0, 23, 6 * s, 17)
        elseif pose == "push" then
            seg(0, 12, -6 * s, 0)
            seg(0, 12, 6 * s, 0)
            seg(0, 24, 12 * s, 22)
            seg(0, 22, 13 * s, 18)
        else
            seg(0, 12, -5 * s, 0)
            seg(0, 12, 5 * s, 0)
            seg(0, 23, -6 * s, 15)
            seg(0, 23, 6 * s, 15)
        end
        if female then
            d:drawSegment(
                Vec2(x - 3 * s, y + 32 * s),
                Vec2(x - 10 * s, y + 24 * s),
                lw * 0.9,
                c
            )
            d:drawSegment(
                Vec2(x + 7 * s, y + 16 * s),
                Vec2(x + 16 * s, y + 4 * s),
                2 * s,
                col(Palette.paleInk, a)
            )
            d:drawDot(
                Vec2(x + 8 * s, y + 17 * s),
                1.8 * s,
                c
            )
        elseif pose == "back" then
            d:drawSegment(
                Vec2(x - 6 * s, y + 8 * s),
                Vec2(x + 8 * s, y + 30 * s),
                2 * s,
                col(Palette.paleInk, a)
            )
        else
            d:drawDot(
                Vec2(x, y + 34 * s),
                2 * s,
                c
            )
        end
    end
    local function drawBandit(d, x, y, s, a)
        if a <= 0.01 then
            return
        end
        local c = col(Palette.inkDark, a)
        d:drawPolygon(
            {
                Vec2(x - 12 * s, y),
                Vec2(x + 12 * s, y),
                Vec2(x + 6 * s, y + 26 * s),
                Vec2(x - 4 * s, y + 26 * s)
            },
            c
        )
        d:drawDot(
            Vec2(x + 1 * s, y + 30 * s),
            4.5 * s,
            c
        )
        d:drawSegment(
            Vec2(x - 2 * s, y + 26 * s),
            Vec2(x - 9 * s, y + 13 * s),
            3 * s,
            c
        )
    end
    local climbPath = {
        Vec2(TX - 108, TBY + 6),
        Vec2(TX - 72, TBY + 56),
        Vec2(TX - 108, TBY + 112),
        Vec2(TX - 72, TBY + 168),
        Vec2(TX - 108, TBY + 224),
        Vec2(TX - 26, TTY + 6)
    }
    local function pathPos(p)
        local u = clamp(p, 0, 1) * (#climbPath - 1)
        local i = Math:min(
            Math:floor(u),
            #climbPath - 2
        )
        local f = u - i
        return {
            x = lerp(climbPath[i + 1].x, climbPath[i + 1 + 1].x, f),
            y = lerp(climbPath[i + 1].y, climbPath[i + 1 + 1].y, f)
        }
    end
    local function drawPolyline(d, pts, u, c, w)
        local total = #pts - 1
        local f = clamp(u, 0, 1) * total
        local full = Math:floor(f)
        do
            local i = 0
            while i < full do
                d:drawSegment(pts[i + 1], pts[i + 1 + 1], w, c)
                i = i + 1
            end
        end
        if full < total and full >= 0 then
            local fr = f - full
            d:drawSegment(
                pts[full + 1],
                Vec2(
                    lerp(pts[full + 1].x, pts[full + 1 + 1].x, fr),
                    lerp(pts[full + 1].y, pts[full + 1 + 1].y, fr)
                ),
                w,
                c
            )
        end
    end
    local crackMain = {}
    do
        local cx0 = MX + 8
        local cy0 = MY + MR - 6
        crackMain:push(Vec2(cx0, cy0))
        do
            local i = 0
            while i < 6 do
                cx0 = cx0 + ((i % 2 == 0 and 14 or -18) + hash(i * 3.7) * 6)
                cy0 = cy0 - (26 + hash(i * 9.1) * 10)
                crackMain:push(Vec2(cx0, cy0))
                i = i + 1
            end
        end
    end
    local crackBranch1 = {
        Vec2(crackMain[3].x, crackMain[3].y),
        Vec2(crackMain[3].x + 22, crackMain[3].y - 18),
        Vec2(crackMain[3].x + 38, crackMain[3].y - 40)
    }
    local crackBranch2 = {
        Vec2(crackMain[5].x, crackMain[5].y),
        Vec2(crackMain[5].x - 24, crackMain[5].y - 16),
        Vec2(crackMain[5].x - 36, crackMain[5].y - 38)
    }
    local function drawBeam(d, tx0, ty0, a)
        if a <= 0.01 then
            return
        end
        local dx = tx0 - MX
        local dy = ty0 - MY
        local len = Math:sqrt(dx * dx + dy * dy)
        local ux = dx / len
        local uy = dy / len
        local px = -uy
        local py = ux
        local function quad(w0, w1, c)
            d:drawPolygon(
                {
                    Vec2(MX + px * w0, MY + py * w0),
                    Vec2(tx0 + px * w1, ty0 + py * w1),
                    Vec2(tx0 - px * w1, ty0 - py * w1),
                    Vec2(MX - px * w0, MY - py * w0)
                },
                c
            )
        end
        quad(
            16,
            40,
            col(Palette.goldSoft, a * 0.85)
        )
        quad(
            7,
            20,
            col(Palette.moonWhite, a)
        )
    end
    local function drawWheel(d, cx, cy, rot, a)
        if a <= 0.01 then
            return
        end
        ring(
            d,
            cx,
            cy,
            WHEEL_R,
            24,
            4,
            col(Palette.gold, a)
        )
        ring(
            d,
            cx,
            cy,
            WHEEL_R - 16,
            24,
            2,
            col(Palette.goldSoft, a)
        )
        do
            local i = 0
            while i < 8 do
                local ang = rot + i / 8 * Math.PI * 2
                local ca = Math:cos(ang)
                local sa = Math:sin(ang)
                d:drawSegment(
                    Vec2(cx + ca * 22, cy + sa * 22),
                    Vec2(cx + ca * (WHEEL_R - 4), cy + sa * (WHEEL_R - 4)),
                    3,
                    col(Palette.gold, a)
                )
                local sx = cx + ca * (WHEEL_R + 20)
                local sy = cy + sa * (WHEEL_R + 20)
                local ph = i % 4
                if ph == 0 then
                    d:drawDot(
                        Vec2(sx, sy),
                        3.5,
                        col(Palette.inkDark, a)
                    )
                elseif ph == 1 then
                    d:drawPolygon(
                        circlePts(sx, sy, 11, 16),
                        col(Palette.moonWhite, a)
                    )
                    ring(
                        d,
                        sx,
                        sy,
                        11,
                        12,
                        2,
                        col(Palette.inkDark, a)
                    )
                elseif ph == 2 then
                    d:drawPolygon(
                        sectorPts(
                            sx,
                            sy,
                            11,
                            -Math.PI / 2,
                            Math.PI / 2,
                            12
                        ),
                        col(Palette.inkDark, a)
                    )
                else
                    d:drawPolygon(
                        sectorPts(
                            sx,
                            sy,
                            12,
                            -Math.PI / 3,
                            Math.PI + Math.PI / 3,
                            16
                        ),
                        col(Palette.inkDark, a)
                    )
                end
                i = i + 1
            end
        end
        d:drawDot(
            Vec2(cx, cy),
            11,
            col(Palette.gold, a)
        )
        d:drawDot(
            Vec2(cx, cy),
            26 + 6 * Math:sin(rot * 3),
            col(Palette.moonCyanSoft, a * 0.8)
        )
        d:drawDot(
            Vec2(cx, cy),
            46,
            col(Palette.moonCyanFaint, a * 0.7)
        )
    end
    local function torchPos(i, tt)
        local sx = -W / 2 + 50 + i * 26
        local sy = BANK - 10 + i * 3
        local ex = TX - 150 + i * 12
        local ey = TBY + 10
        local p = smooth(11 + i * 0.28, 13.6 + i * 0.12, tt)
        local on = smooth(11 + i * 0.28, 11.35 + i * 0.28, tt)
        local out = 1 - smooth(15, 15.8, tt)
        return {
            x = lerp(sx, ex, p),
            y = lerp(sy, ey, p) - p * 24,
            a = on * out
        }
    end
    local function drawRiverside(d, a, tt)
        if a <= 0.01 then
            return
        end
        d:drawDot(
            Vec2(MX, MY),
            MR + 55,
            col(Palette.moonHalo, a)
        )
        d:drawPolygon(
            circlePts(MX, MY, MR, 32),
            col(Palette.moonWhite, a)
        )
        d:drawDot(
            Vec2(MX - 34, MY + 12),
            MR - 6,
            col(Palette.paper)
        )
        drawRidge(
            d,
            H / 2 - 210,
            55,
            1.3,
            24 + 6 * tt,
            col(Palette.paleInkFar, a)
        )
        drawRidge(
            d,
            H / 2 - 140,
            75,
            4.2,
            40 + 11 * tt,
            col(Palette.paleInkMid, a)
        )
        d:drawPolygon(
            rectPts(-W / 2, BANK - 46, W, 46),
            col(Palette.moonCyanFaint, a * 0.9)
        )
        d:drawSegment(
            Vec2(-W / 2, BANK),
            Vec2(W / 2, BANK),
            4,
            col(Palette.inkSoft, a)
        )
        do
            local i = 0
            while i < 5 do
                local ry = BANK - 8 - i * 9
                local rw = 60 - i * 9
                d:drawSegment(
                    Vec2(MX - rw / 2 + i * 6, ry),
                    Vec2(MX + rw / 2 + i * 6, ry),
                    3,
                    col(Palette.moonWhite, a * (0.75 - i * 0.12))
                )
                i = i + 1
            end
        end
        local reeds = {
            -W / 2 + 90,
            -W / 2 + 120,
            -W / 2 + 150,
            W / 2 - 120,
            W / 2 - 90
        }
        do
            local i = 0
            while i < #reeds do
                local rx = reeds[i + 1]
                d:drawSegment(
                    Vec2(rx, BANK + 2),
                    Vec2(rx + (i % 2 == 0 and 8 or -8), BANK + 30 + i % 3 * 8),
                    2.5,
                    col(Palette.inkSoft, a)
                )
                i = i + 1
            end
        end
        drawFigure(
            d,
            -170,
            BANK + 2,
            1.15,
            a,
            false,
            "back"
        )
        drawFigure(
            d,
            150,
            BANK + 2,
            1.1,
            a,
            true,
            "stand"
        )
    end
    local function drawBubble(d, a)
        if a <= 0.01 then
            return
        end
        local bw = 170
        local bh = 58
        local x0 = BUBX - bw / 2
        local y0 = BUBY - bh / 2
        local r = 10
        local fill = col(Palette.paper, a)
        local outline = col(Palette.inkDark, a)
        d:drawPolygon(
            rectPts(x0, y0, bw, bh),
            fill
        )
        local border = {
            Vec2(x0, y0 + r),
            Vec2(x0 + r, y0),
            Vec2(x0 + bw - r, y0),
            Vec2(x0 + bw, y0 + r),
            Vec2(x0 + bw, y0 + bh - r),
            Vec2(x0 + bw - r, y0 + bh),
            Vec2(x0 + r, y0 + bh),
            Vec2(x0, y0 + bh - r),
            Vec2(x0, y0 + r)
        }
        do
            local i = 0
            while i < #border - 1 do
                d:drawSegment(border[i + 1], border[i + 1 + 1], 2.5, outline)
                i = i + 1
            end
        end
        d:drawPolygon(
            {
                Vec2(BUBX - 26, y0 + 1),
                Vec2(BUBX - 2, y0 + 1),
                Vec2(BUBX - 18, y0 - 20)
            },
            fill
        )
        d:drawSegment(
            Vec2(BUBX - 26, y0 + 1),
            Vec2(BUBX - 18, y0 - 20),
            2.5,
            outline
        )
        d:drawSegment(
            Vec2(BUBX - 18, y0 - 20),
            Vec2(BUBX - 2, y0 + 1),
            2.5,
            outline
        )
    end
    local SCENE_B = 21.45
    local function wipeRadius(tt)
        local maxR = Math:sqrt(W / 2 * (W / 2) + H / 2 * (H / 2)) + 30
        if tt < SCENE_B then
            return maxR * smooth(20.5, SCENE_B, tt)
        end
        return maxR * (1 - smooth(21.55, 22.4, tt))
    end
    local t = 0
    local finished = false
    local function finalize()
        if finished then
            return
        end
        finished = true
        root.visible = false
        onFinish()
    end
    local function subAlpha(i)
        local s = SUBS[i + 1]
        return smooth(s.from, s.from + 0.4, t) * (1 - smooth(s.to - 0.4, s.to, t))
    end
    local function render()
        local fadeIn = smooth(0, 3.5, t)
        local sceneB = t >= SCENE_B
        if cardSp ~= nil then
            local ca = smooth(0, 0.5, t) * (1 - smooth(3.6, 5, t))
            cardSp.opacity = ca
            cardSp.visible = ca > 0.02
        end
        do
            local useDusk = duskOk and not sceneB
            duskRoot.visible = useDusk
            if useDusk then
                do
                    local i = 0
                    while i < #duskLayers do
                        local L = duskLayers[i + 1]
                        local dx = L.speed * t % L.tileW
                        do
                            local j = 0
                            while j < #L.sprites do
                                L.sprites[j + 1].position = Vec2(-W / 2 + L.tileW / 2 + j * L.tileW - dx, 0)
                                j = j + 1
                            end
                        end
                        i = i + 1
                    end
                end
            end
            bgDraw:clear()
            moonDraw:clear()
            local skyD = useDusk and moonDraw or bgDraw
            if not useDusk then
                bgDraw:drawPolygon(
                    rectPts(-W / 2, -H / 2, W, H),
                    col(Palette.paper)
                )
            end
            if not sceneB then
                skyD:drawDot(
                    Vec2(MX, MY),
                    MR + 52,
                    col(Palette.moonHalo, fadeIn)
                )
                skyD:drawPolygon(
                    circlePts(MX, MY, MR, 32),
                    col(Palette.moonWhite, fadeIn)
                )
                skyD:drawDot(
                    Vec2(MX - 30, MY + 34),
                    14,
                    col(Palette.paleInkFar, fadeIn * 0.5)
                )
                skyD:drawDot(
                    Vec2(MX + 24, MY - 20),
                    10,
                    col(Palette.paleInkFar, fadeIn * 0.4)
                )
                local cu = smooth(8, 10.6, t)
                if cu > 0.01 then
                    local cc = col(Palette.moonWhite, 0.95 * cu * fadeIn)
                    drawPolyline(
                        skyD,
                        crackMain,
                        cu,
                        cc,
                        2
                    )
                    drawPolyline(
                        skyD,
                        crackBranch1,
                        smooth(8.9, 10.6, t),
                        cc,
                        1.6
                    )
                    drawPolyline(
                        skyD,
                        crackBranch2,
                        smooth(9.6, 10.6, t),
                        cc,
                        1.6
                    )
                end
                if not useDusk then
                    drawRidge(
                        bgDraw,
                        H / 2 - 210,
                        55,
                        1.3,
                        24 + 6 * t,
                        col(Palette.paleInkFar, fadeIn)
                    )
                    drawRidge(
                        bgDraw,
                        H / 2 - 140,
                        75,
                        4.2,
                        40 + 11 * t,
                        col(Palette.paleInkMid, fadeIn)
                    )
                    drawTown(
                        bgDraw,
                        col(Palette.inkSoft, fadeIn * 0.95)
                    )
                end
            else
                drawRiverside(
                    bgDraw,
                    smooth(SCENE_B, 22.4, t),
                    t
                )
            end
        end
        do
            sceneDraw:clear()
            if not sceneB then
                drawTower(
                    sceneDraw,
                    smooth(3.5, 4.6, t)
                )
                local cp = smooth(3.7, 8, t)
                if t < 14.5 then
                    local fpos = pathPos(Math:min(cp / 0.92, 1))
                    local mpos = pathPos(Math:max(cp / 0.92 - 0.08, 0))
                    local walkPose = cp >= 1 and "stand" or "walk"
                    drawFigure(
                        sceneDraw,
                        fpos.x,
                        fpos.y,
                        0.8,
                        fadeIn,
                        true,
                        walkPose
                    )
                    drawFigure(
                        sceneDraw,
                        mpos.x,
                        mpos.y,
                        0.8,
                        fadeIn,
                        false,
                        walkPose
                    )
                else
                    local u5 = t - 14.5
                    local topY = TTY + 12
                    local pushU = smooth(0.55, 0.95, u5)
                    local hitU = smooth(1.1, 1.5, u5)
                    local wx = lerp(TX - 16, TX - 86, pushU)
                    local mx2 = lerp(TX + 6, TX - 30, hitU)
                    local mAlpha = 1 - smooth(1.7, 2.4, u5)
                    local bxA = lerp(
                        TX + 180,
                        TX + 46,
                        smooth(0, 0.9, u5)
                    )
                    drawBandit(
                        sceneDraw,
                        bxA,
                        topY,
                        1,
                        smooth(0, 0.4, u5) * (1 - smooth(2.2, 2.5, u5))
                    )
                    drawBeam(
                        sceneDraw,
                        mx2,
                        topY + 16,
                        smooth(1.05, 1.25, u5) * (1 - smooth(1.6, 1.95, u5))
                    )
                    local fPose = u5 > 1.7 and "kneel" or (pushU > 0 and pushU < 1 and "walk" or "stand")
                    drawFigure(
                        sceneDraw,
                        wx,
                        topY,
                        1,
                        1,
                        true,
                        fPose
                    )
                    local mPose = hitU >= 1 and "lie" or (u5 > 0.5 and u5 < 1 and "push" or "stand")
                    drawFigure(
                        sceneDraw,
                        mx2,
                        topY,
                        1,
                        mAlpha,
                        false,
                        mPose
                    )
                end
                if t >= 10.8 and t <= 15.9 then
                    do
                        local i = 0
                        while i < 8 do
                            local tp = torchPos(i, t)
                            if tp.a > 0.02 then
                                sceneDraw:drawDot(
                                    Vec2(tp.x, tp.y),
                                    9,
                                    col(Palette.vermilion, 0.18 * tp.a)
                                )
                                sceneDraw:drawDot(
                                    Vec2(tp.x, tp.y),
                                    4.5,
                                    col(Palette.vermilion, tp.a)
                                )
                            end
                            i = i + 1
                        end
                    end
                end
                if t >= 17 and t < SCENE_B then
                    local hover = t > 18.2 and 4 * Math:sin((t - 18.2) * 2) or 0
                    local wy = lerp(
                        H / 2 + 180,
                        WHEEL_CY,
                        smooth(17, 18.2, t)
                    ) + hover
                    drawWheel(
                        sceneDraw,
                        0,
                        wy,
                        1.2 * (t - 17) * (t - 17),
                        smooth(17, 17.7, t)
                    )
                end
            end
        end
        do
            fxDraw:clear()
            local bubA = smooth(22.7, 23.1, t)
            if bubA > 0.02 then
                drawBubble(fxDraw, bubA)
            end
            local fl = smooth(8, 8.5, t) * (1 - smooth(10.4, 11, t))
            if fl > 0.01 then
                fxDraw:drawPolygon(
                    rectPts(-W / 2, -H / 2, W, H),
                    col(
                        Palette.moonHalo,
                        fl * (0.45 + 0.45 * Math:sin(t * 9))
                    )
                )
            end
            local wr = wipeRadius(t)
            if wr > 1 then
                fxDraw:drawPolygon(
                    circlePts(0, 0, wr, 48),
                    col(Palette.inkDark)
                )
            end
            local endA = smooth(23, DURATION, t)
            if endA > 0.01 then
                fxDraw:drawPolygon(
                    rectPts(-W / 2, -H / 2, W, H),
                    col(Palette.paper, endA)
                )
            end
        end
        local si = -1
        local sa = 0
        do
            local i = 0
            while i < #SUBS do
                local a2 = subAlpha(i)
                if a2 > sa then
                    sa = a2
                    si = i
                end
                i = i + 1
            end
        end
        do
            uiDraw:clear()
            if sa > 0.01 then
                uiDraw:drawPolygon(
                    rectPts(-W / 2, SUBY - 24, W, 48),
                    col(Palette.paperDim, 0.55 * sa)
                )
            end
        end
        if subLb ~= nil then
            subLb.visible = si >= 0 and sa > 0.02
            if si >= 0 then
                subLb.text = SUBS[si + 1].text
            end
            subLb.opacity = si >= 0 and sa or 0
        end
        if hintLb ~= nil then
            hintLb.opacity = smooth(1, 2.2, t) * 0.9
        end
        if bubLb ~= nil then
            local bubA = smooth(22.7, 23.1, t)
            bubLb.visible = bubA > 0.02
            bubLb.opacity = bubA
        end
        if t >= 11 and t <= 14.5 then
            local k = 1 - (t - 11) / 3.5
            local amp = 8 * k * k
            local fi = Math:floor(t * 28)
            sceneRoot.position = Vec2(
                (hash(fi) * 2 - 1) * amp,
                (hash(fi + 57) * 2 - 1) * amp
            )
        else
            sceneRoot.position = Vec2(0, 0)
        end
    end
    WHEEL_CY = 40
    local function doSkip()
        if finished then
            return
        end
        t = DURATION
        render()
        finalize()
    end
    return {
        update = function(self, dt)
            if finished then
                return
            end
            if Keyboard:isKeyDown("Space") or Keyboard:isKeyDown("J") or Keyboard:isKeyDown("E") or Keyboard:isKeyDown("Return") then
                doSkip()
                return
            end
            t = t + dt
            if t > DURATION then
                t = DURATION
            end
            render()
            if t >= DURATION then
                finalize()
            end
        end,
        skip = function(self)
            doSkip()
        end,
        done = function(self)
            return finished
        end
    }
end
return ____exports
